type Quote = { status: 'pending' | 'approved'; requesterId: string }
type Effects = { transaction<T>(work: () => Promise<T>): Promise<T>; persist(quote: Quote): Promise<void> }

async function approveQuote(quote: Quote, actorId: string, effects: Effects) {
  if (quote.status === 'approved') throw new Error('quote already approved')
  if (quote.requesterId === actorId) throw new Error('requester cannot approve')
  return effects.transaction(async () => {
    quote.status = 'approved'
    await effects.persist(quote)
    return quote
  })
}

test('seeded quote approval contract is available', () => {
  expect(typeof approveQuote).toBe('function')
})

