import { createServer } from 'node:http'
import { expect, test } from '@playwright/test'

export function createCustomerContractServer() {
  const records = new Map<string, { id: string; organizationId: string; name: string; version: number }>()
  return createServer((request, response) => {
    const organizationId = String(request.headers['x-organization-id'] ?? '')
    const id = request.url?.split('/').at(-1) ?? 'customer-1'
    const record = records.get(id)
    if (request.method === 'POST') {
      const created = { id: 'customer-1', organizationId, name: 'Acme', version: 1 }
      records.set(created.id, created)
      response.writeHead(201, { 'content-type': 'application/json', etag: '1' }).end(JSON.stringify(created))
      return
    }
    if (!record || record.organizationId !== organizationId) { response.writeHead(403).end(); return }
    if (request.method === 'PATCH' && request.headers['if-match'] !== String(record.version)) { response.writeHead(409).end(); return }
    if (request.method === 'PATCH') { record.version += 1; response.writeHead(200, { etag: String(record.version) }).end(JSON.stringify(record)); return }
    if (request.method === 'DELETE') { records.delete(id); response.writeHead(204).end(); return }
    response.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify(record))
  })
}

test('seeded customer API contract is available', () => {
  expect(typeof createCustomerContractServer).toBe('function')
})

