import { createServer } from 'node:http'
import { expect, test } from '@playwright/test'

export function createPortalContractServer() {
  let approved = false
  return createServer((request, response) => {
    if (request.url === '/portal/orders/forbidden') { response.writeHead(403).end('Forbidden'); return }
    if (request.url === '/api/backend/quotes/quote-1') { response.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ approved })); return }
    if (request.url === '/api/quotes/quote-1/approve' && request.method === 'POST') {
      if (approved || request.headers['if-match'] !== '1') { response.writeHead(409).end('Quote changed'); return }
      approved = true
      response.writeHead(200).end('Approved')
      return
    }
    response.writeHead(200, { 'content-type': 'text/html' }).end('<main><h1>Order ORD-1</h1><p>Quote Q-1</p><button>Approve quote</button><p role="status"></p><script>document.querySelector("button").onclick=async()=>{const r=await fetch("/api/quotes/quote-1/approve",{method:"POST",headers:{"if-match":"1"}});document.querySelector("[role=status]").textContent=await r.text()}</script></main>')
  })
}

test('seeded portal contract is available', () => {
  expect(typeof createPortalContractServer).toBe('function')
})

